      arMoveCfg E e c a ⟨N + 1, by omega⟩

private lemma arWriteCfg_run {Γ : Type} [Fintype Γ] [DecidableEq Γ] {N : ℕ}
    (E : Option Γ ↪ ArBlock N) (e : Bool ↪ Γ) (M : FinTM Γ) {x : List Bool}
    (c : Cfg M.k Γ M.State (x.map e)) (a : Action M.k Γ M.State) :
